<?php require_once __DIR__.'/../includes/config.php';require_once __DIR__.'/../includes/db.php';require_once __DIR__.'/../includes/functions.php';require_once __DIR__.'/../includes/security.php';require_once __DIR__.'/../includes/auth.php';$stores=$pdo->query("SELECT s.*,COUNT(p.id) product_count FROM smes s LEFT JOIN products p ON p.sme_id=s.id AND p.status='active' WHERE s.status='active' GROUP BY s.id ORDER BY s.trust_score DESC")->fetchAll();$pageTitle='Stores';include __DIR__.'/../includes/partials/header.php';?><h1>Local Stores</h1><div class="store-grid"><?php foreach($stores as $store):?><div class="store-card"><h2><?=e($store['business_name'])?></h2><p><?=e($store['district'])?></p><p>Trust Score: <strong><?=number_format((float)$store['trust_score'],0)?>/100</strong></p><p><?=$store['product_count']?> products</p><a href="store.php?id=<?=$store['id']?>">View Store</a></div><?php endforeach;?></div><?php include __DIR__.'/../includes/partials/footer.php';?>